"""Neighbour content for prokhor, agafya, mila, vera, kuzmich: people/<id>.tsv (docs/CONTENT.md).

Each character: LINES (when, ru, en); REQS (gap, months, when, hearts, needs, reward, ru, en,
reply_ru, reply_en[, sets]); NOTES (gap, months, when, hearts, needs-flags, reward, ru, en).
"""
from common import write

COLS = "t n gap months when hearts needs reward text_ru text_en reply_ru reply_en sets".split()


def build(lines, reqs, notes):
    rows = []
    for when, ru, en in lines:
        rows.append(["line", "", "", "", when, "", "", "", ru, en, "", "", ""])
    for i, r in enumerate(reqs, 1):
        gap, months, when, hearts, needs, reward, ru, en, rru, ren, *sets = r
        rows.append(["req", i, gap, months, when, hearts, needs, reward, ru, en, rru, ren, sets[0] if sets else ""])
    for i, (gap, months, when, hearts, needs, reward, ru, en) in enumerate(notes, 1):
        rows.append(["note", i, gap, months, when, hearts, needs, reward, ru, en, "", "", ""])
    return rows


